// Paso 1: Validar entrada directamente
const input = items[0].json;

if (!input || typeof input !== "object" || !input.date || !Array.isArray(input.busyEvents)) {
  return [{ json: { error: "Missing or invalid 'date' or 'busyEvents' in input" } }];
}

// Paso 2: Preparar eventos ocupados
const events = input.busyEvents;
const seen = new Set();
const filtered = events.filter(ev => {
  const key = ev.start + ev.end;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

filtered.sort((a, b) => new Date(a.start) - new Date(b.start));

// Paso 3: Configurar rango de horario (8 AM a 6 PM en UTC-6)
const slotDuration = 30 * 60 * 1000; // 30 minutos
const timeZone = 'America/Mexico_City';

const opening = new Date(`${input.date}T08:00:00-06:00`);
const closing = new Date(`${input.date}T18:00:00-06:00`);

const slots = [];
let cursor = new Date(opening);

// Paso 4: Generar slots disponibles antes de eventos
for (const ev of filtered) {
  const start = new Date(ev.start);
  const end = new Date(ev.end);

  while (cursor.getTime() + slotDuration <= start.getTime()) {
    const slotEnd = new Date(cursor.getTime() + slotDuration);

    slots.push({
      start: cursor.toLocaleString('sv-SE', { timeZone }),
      end: slotEnd.toLocaleString('sv-SE', { timeZone }),
      label: `${cursor.toLocaleTimeString('en-US', { timeZone, hour: 'numeric', minute: '2-digit', hour12: true })} - ${slotEnd.toLocaleTimeString('en-US', { timeZone, hour: 'numeric', minute: '2-digit', hour12: true })}`
    });

    cursor = slotEnd;
  }

  if (cursor < end) cursor = new Date(end);
}

// Paso 5: Generar slots después del último evento
while (cursor.getTime() + slotDuration <= closing.getTime()) {
  const slotEnd = new Date(cursor.getTime() + slotDuration);

  slots.push({
    start: cursor.toLocaleString('sv-SE', { timeZone }),
    end: slotEnd.toLocaleString('sv-SE', { timeZone }),
    label: `${cursor.toLocaleTimeString('en-US', { timeZone, hour: 'numeric', minute: '2-digit', hour12: true })} - ${slotEnd.toLocaleTimeString('en-US', { timeZone, hour: 'numeric', minute: '2-digit', hour12: true })}`
  });

  cursor = slotEnd;
}

// Paso 6: Devolver resultado
return slots.map(s => ({ json: s }));

let raw = items[0].json.query;
let parsed;
let busyEvents = [];
let appointmentDate = "";

// Paso 1: Intentar parsear el string
try {
  parsed = JSON.parse(raw);
} catch (e) {
  return [{ json: { error: "Invalid JSON in 'query'" } }];
}

// Paso 2: Si parsed es un array (caso: solo lista de eventos)
if (Array.isArray(parsed)) {
  busyEvents = parsed;
  if (busyEvents.length > 0 && busyEvents[0].start) {
    appointmentDate = busyEvents[0].start.split("T")[0];
  } else {
    // fallback si no hay eventos
    appointmentDate = new Date().toISOString().split("T")[0];
  }
}
// Paso 3: Si parsed es un objeto con busyEvents
else if (typeof parsed === "object" && parsed !== null && Array.isArray(parsed.busyEvents)) {
  busyEvents = parsed.busyEvents;
  appointmentDate = parsed.date || (
    busyEvents.length > 0 && busyEvents[0].start
      ? busyEvents[0].start.split("T")[0]
      : new Date().toISOString().split("T")[0]
  );
} else {
  return [{ json: { error: "Missing or invalid 'busyEvents'" } }];
}

// Paso 4: Retornar el objeto correcto
return [
  {
    json: {
      date: appointmentDate,
      busyEvents: busyEvents
    }
  }
];
